theme.css:
/* theme: Majority Marker | A power shift and a chip crash mark the day, logged in ballot-blue ink on a bright news-paper sheet. */
/* mood: good */
/* layout: hero=poster; major-events=banner/grid-2; political-news=numbered/stack; financial-news=stat/grid-3; tech-news=outline/grid-2; entertainment-news=plain/stack; sports=timeline/masonry; music-releases=plain/stack; stock-analysis=stat/grid-3; outlook=tile/grid-2 */

.diary-page {
  --paper: #e0f0e4;
  --paper-alt: #d0e6d4;
  --ink: #0f2d1a;
  --ink-soft: #1f4830;
  --muted: #3a6b4e;
  --accent: #0f6b35;
  --accent-ink: #f0fff4;
  --rule: #b8d4be;
  --font-display: var(--ff-instrument), Georgia, serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-inter), system-ui, sans-serif;
}

.diary-page .diary-hero {
  background: var(--accent);
  border-bottom: 0;
  padding-block: 2.5rem 3.5rem;
  position: relative;
}

.diary-page .diary-hero::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 4px;
  background: var(--accent-ink);
  opacity: 0.5;
}

.diary-page .diary-hero-inner {
  padding-block: 0;
}

.diary-page .diary-crumbs a {
  color: var(--accent-ink);
}

.diary-page .diary-crumbs a:hover {
  color: var(--accent-ink);
  opacity: 0.8;
}

.diary-page .diary-kicker {
  color: var(--accent-ink);
  letter-spacing: 0.2em;
  font-weight: 700;
}

.diary-page .diary-title {
  font-weight: 400;
  font-size: clamp(3rem, 10vw, 7.5rem);
  line-height: 0.92;
  letter-spacing: -0.01em;
  max-width: none;
  text-transform: none;
}

.diary-page .diary-summary {
  font-size: clamp(1.1rem, 2vw, 1.4rem);
  color: var(--accent-ink);
  max-width: 44rem;
  border-left: 3px solid var(--accent-ink);
  padding-left: 1.25rem;
  opacity: 0.95;
}

.diary-page .diary-theme-note {
  color: var(--accent-ink);
  opacity: 0.9;
}

.diary-page .diary-theme-name {
  background: var(--accent-ink);
  color: var(--accent);
  border-radius: 0;
  font-weight: 700;
}

.diary-page .diary-toc {
  background: var(--paper);
  border-bottom: 1px solid var(--rule);
}

@media (min-width: 1024px) {
  .diary-page .diary-toc {
    background: none;
    border: 0;
  }
}

.diary-page .diary-toc-link {
  color: var(--muted);
}

.diary-page .diary-toc-link.is-active {
  color: var(--ink);
}

.diary-page .diary-toc-number {
  color: var(--accent);
}

.diary-page .diary-section {
  border-top-color: var(--rule);
}

.diary-page .diary-section-number {
  color: var(--accent);
}

.diary-page .diary-section-title {
  font-weight: 400;
  letter-spacing: -0.01em;
}

.diary-page .diary-section-head::after {
  content: "";
  flex: 1;
  height: 1px;
  background: var(--rule);
  margin-left: 1rem;
  align-self: center;
}

.diary-page .diary-prose {
  color: var(--ink-soft);
}

.diary-page .diary-prose a {
  color: var(--accent);
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
}

.diary-page .diary-prose strong {
  color: var(--ink);
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

.diary-page .diary-prose ol > li::marker {
  color: var(--accent);
}

.diary-page .diary-prose pre {
  background: var(--paper-alt);
  border-color: var(--rule);
}

.diary-page [data-section="major-events"] .diary-card--banner .diary-card-inner {
  border-color: var(--rule);
  border-radius: 0.25rem;
}

.diary-page [data-section="major-events"] .diary-card--banner .diary-card-title {
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 1.1rem;
  font-weight: 600;
  letter-spacing: 0.02em;
}

.diary-page [data-section="major-events"] .diary-card--banner .diary-card-body {
  color: var(--ink-soft);
}

.diary-page [data-section="political-news"] .diary-card--numbered .diary-card-inner {
  border-left: 1px solid var(--rule);
  padding-left: 1.5rem;
}

.diary-page [data-section="political-news"] .diary-card--numbered .diary-card-index {
  font-size: 2.75rem;
  font-weight: 700;
  color: var(--accent);
}

.diary-page [data-section="financial-news"] .diary-card--stat .diary-card-inner {
  border-top-color: var(--accent);
}

.diary-page [data-section="financial-news"] .diary-card--stat .diary-card-figure {
  font-size: clamp(2.5rem, 10cqi, 3.5rem);
  font-weight: 700;
  color: var(--accent);
}

.diary-page [data-section="tech-news"] .diary-card--outline .diary-card-inner {
  border-color: var(--rule);
  border-radius: 0;
  background: var(--paper-alt);
}

.diary-page [data-section="entertainment-news"] .diary-card--plain .diary-card-body {
  font-size: 1.12rem;
}

.diary-page [data-section="sports"] .diary-card--timeline .diary-card-inner {
  padding-left: 2rem;
}

.diary-page [data-section="sports"] .diary-card--timeline .diary-card-inner::before {
  left: 0.5rem;
  background: var(--rule);
}

.diary-page [data-section="sports"] .diary-card--timeline .diary-card-inner::after {
  left: 0.15rem;
  width: 0.6rem;
  height: 0.6rem;
  background: var(--accent);
  box-shadow: 0 0 0 4px var(--paper);
}

.diary-page [data-section="music-releases"] .diary-card--plain .diary-card-body {
  font-size: 1.08rem;
}

.diary-page [data-section="stock-analysis"] .diary-spark {
  background: var(--paper-alt);
  border-color: var(--rule);
}

.diary-page [data-section="stock-analysis"] .diary-spark-value {
  color: var(--ink);
}

.diary-page [data-section="stock-analysis"] .diary-spark.is-down .diary-spark-change {
  color: var(--accent);
}

.diary-page [data-section="outlook"] .diary-card--tile .diary-card-inner {
  background: var(--paper-alt);
  padding: 1.5rem;
}

.diary-page .diary-card--tile .diary-card-title {
  color: var(--ink);
}

.diary-page .diary-card--tile .diary-card-body {
  color: var(--ink-soft);
}

.diary-page .diary-card-thread {
  border-color: var(--accent);
  color: var(--accent);
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

.diary-page .diary-footer {
  border-top-color: var(--rule);
}

.diary-page .diary-footer a {
  color: var(--ink);
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

@media (min-width: 1024px) {
  .diary-page .diary-toc-label {
    color: var(--muted);
  }

  .diary-page .diary-toc-list {
    border-left-color: var(--rule);
  }

  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
  }
}

.diary-page [data-section="major-events"] .diary-card--banner .diary-card-title {
  font-size: 1.2rem;
  padding: 1rem 1.25rem;
}

.diary-page [data-section="tech-news"] .diary-card--outline .diary-card-title {
  font-size: 1.3rem;
}

.diary-page [data-section="sports"] .diary-card--timeline .diary-card-title {
  font-size: 1.15rem;
}

.diary-page [data-section="outlook"] .diary-card--tile .diary-card-title {
  font-size: 1.25rem;
}

.diary-page .diary-prose a {
  text-decoration: none;
  border-bottom: 1px solid var(--accent);
}

.diary-page .diary-prose a:hover {
  border-bottom-color: var(--ink);
  color: var(--ink);
}

@media (prefers-reduced-motion: reduce) {
  .diary-page *,
  .diary-page *::before,
  .diary-page *::after {
    animation: none !important;
    transition: none !important;
  }
}
